  1	"""Deterministic water balance for the Kvartsitovye Gorki sump."""
  2	from dataclasses import dataclass
  3	from math import isfinite
  4	
  5	PUMP_CAPACITY_M3_H = 300.0
  6	
  7	@dataclass
  8	class WaterBalance:
  9	    volume_m3: float
 10	    inflow_m3_h: float
 11	    pump1_on: bool = True
 12	    pump2_on: bool = True
 13	
 14	    def __post_init__(self):
 15	        for name in ('volume_m3', 'inflow_m3_h'):
 16	            value = getattr(self, name)
 17	            if not isfinite(value) or value < 0:
 18	                raise ValueError(f'{name} must be finite and nonnegative')
 19	
 20	    def step(self, seconds: float) -> dict:
 21	        if not isfinite(seconds) or seconds <= 0:
 22	            raise ValueError('seconds must be finite and positive')
 23	        if not isfinite(self.inflow_m3_h) or self.inflow_m3_h < 0:
 24	            raise ValueError('inflow_m3_h must be finite and nonnegative')
 25	        incoming = self.inflow_m3_h * seconds / 3600.0
 26	        requested = PUMP_CAPACITY_M3_H * (self.pump1_on + self.pump2_on) * seconds / 3600.0
 27	        available = self.volume_m3 + incoming
 28	        pumped = min(available, requested)
 29	        self.volume_m3 = max(0.0, available - pumped)
 30	        return {
 31	            'volume_m3': self.volume_m3,
 32	            'inflow_m3_h': self.inflow_m3_h,
 33	            'pump1_on': self.pump1_on,
 34	            'pump2_on': self.pump2_on,
 35	            'requested_outflow_m3_h': PUMP_CAPACITY_M3_H * (self.pump1_on + self.pump2_on),
 36	            'actual_pumped_m3': pumped,
 37	            'incoming_m3': incoming,
 38	        }
